body.script:
((w) => {
    w['GSEA_init'] = {
        debug: false,

        loginURI: 'https://login.gaijin.net',
        embedURI: 'https://embed.gaijin.net',

        embed: {
            template: 'default',
            page: 'default',
            language: 'en',
        },

        autoLogin: true,
        sessionPolling: true,
        sessionPollingInterval: 10 * 60000,
        uid: '',
        jwt: '',
        queryContext: 'https://login.gaijin.net/en/sso/reLogin/?return_url=aHR0cHM6Ly9lbmxpc3RlZC5uZXQvZW4vZXh0TG9naW4vP2Zyb209ZW4lMkZpJTJGbG9nbyUyRmdhaWppbi1sb2dvLnN2ZyUyRg%3D%3D&crc=daa29df311ecf12eb71586e781b90fb4&public_key=A0lpDCbCoP3JqdfoudMe&domain=enlisted.net&base_return_url=1&refresh_token=1',
        onLoad: (client) => {
            client.on('change', (newSession, oldSession) => {
                if (newSession.uid !== oldSession.uid) {
                    if (newSession.rt) {
                        window.location = `/extLogin?refresh_token=${newSession.rt}&from=${window.location.pathname}`
                    }

                    if (!newSession.uid) {
                        $.post('/logout', {_csrf: $('meta[name="csrf-token"]').attr('content')}, function (data) {
                            window.location.reload();
                        });
                    }
                }
            });

            client.on('logout', () => {
                $.post('/logout', {_csrf: $('meta[name="csrf-token"]').attr('content')}, function (data) {
                    window.location.reload();
                });
            });
        }
    }
})(window);

((w) => {
    const toGSEALangMap = {
        'jp': 'ja',
        'cz': 'cs',
    };
    const toGSEALang = (lng) => (toGSEALangMap[lng] || lng);

    const fromGSEALangMap = {
        'ja': 'jp',
        'cs': 'cz',
    };
    const fromGSEALang = (lng) => (fromGSEALangMap[lng] || lng);

    w['GCM_init'] = {
        langList: ['en', 'de', 'ru'],
        lang: 'en',

        mobileBreakpoint: 640,
        maxContentWidth: '100%',

        links: false,
        shop: false,

        onLoad: [(client) => {
            client.on('lang_change', (lang) => {
                lang = fromGSEALang(lang);
                window.location = window.location.origin + "/" + lang + "/";
            });
        }],
    };
})(window);
